from manim import *
import numpy as np

class CotWavePath(Scene):
    def construct(self):
        axes = Axes(
            x_range=[-2*PI, 2*PI, PI/2],
            y_range=[-6, 6, 2],
            x_length=10,
            y_length=6,
        )

        labels = axes.get_axis_labels(MathTex("x"), MathTex("y"))
        self.play(Create(axes), Write(labels))

        xs = np.linspace(-2*PI, 2*PI, 3000)
        segments = []
        buf = []

        for x in xs:
            if abs(np.sin(x)) < 0.04:
                if len(buf) > 1:
                    segments.append(np.array(buf))
                buf = []
            else:
                y = np.cos(x) / np.sin(x)
                buf.append(axes.c2p(x, y))

        if len(buf) > 1:
            segments.append(np.array(buf))

        curves = VGroup()
        for pts in segments:
            m = VMobject().set_points_smoothly(pts)
            curves.add(m)

        for c in curves:
            self.play(Create(c), run_time=0.25)

        self.wait(1)

