import numpy as np

class SecWavePath(Scene):
    def construct(self):
        x_min, x_max = -2 * PI, 2 * PI
        y_min, y_max = -5, 5

        axes = Axes(
            x_range=[x_min, x_max, PI/2],
            y_range=[y_min, y_max, 1],
            x_length=10,
            y_length=6,
        )
        labels = axes.get_axis_labels(MathTex("x"), MathTex("y"))
        self.play(Create(axes), Write(labels))

        xs = np.linspace(x_min, x_max, 6000)
        segments = []
        buf = []
        eps = 0.02

        for x in xs:
            c = np.cos(x)
            if abs(c) < eps:
                if len(buf) > 1:
                    segments.append(np.array(buf))
                buf = []
            else:
                y = 1.0 / c
                if y < y_min * 2 or y > y_max * 2:
                    if len(buf) > 1:
                        segments.append(np.array(buf))
                    buf = []
                else:
                    buf.append(axes.c2p(x, y))
        if len(buf) > 1:
            segments.append(np.array(buf))

        curves = VGroup()
        for pts in segments:
            m = VMobject().set_points_smoothly(pts)
            curves.add(m.set_stroke(width=3))

        asym_xs = [ (2*k+1)*PI/2 for k in range(-3,4) ]
        for ax_x in asym_xs:
            if x_min < ax_x < x_max:
                x_pt = axes.c2p(ax_x, 0)[0]
                line = DashedLine(
                    [x_pt, axes.c2p(0, y_min)[1], 0],
                    [x_pt, axes.c2p(0, y_max)[1], 0],
                    stroke_width=1
                )
                self.add(line)

        for c in curves:
            self.play(Create(c), run_time=0.25)
        self.wait(1)

