from manim import *

class DemonstrateObjectHierarchyWhereSubmobjectsMove(Scene):
    def construct(self):
        circle = Circle(radius=1.5, color=BLUE)
        dots = VGroup(*[Dot(circle.point_at_angle(i*PI/4), color=RED, radius=0.1)
                       for i in range(8)])
        group = VGroup(circle, dots)
        self.play(Create(group))
        self.play(group.animate.shift(RIGHT*2 + UP*1), run_time=2)
        self.wait(1)
